import { ApiPropertyOptional } from "@nestjs/swagger"
import { IsIn, IsInt, Max, Min } from "class-validator"
import {
  CURRENCIES,
  IfGroupPresent,
  IsGreaterOrEqualTo,
  RequiredWith,
  SALARY_MAX_VALUE,
  SALARY_PERIODS,
} from "../../core/validation/structured"

const SALARY_FIELDS = ["salaryMin", "salaryMax", "salaryCurrency", "salaryPeriod"]
const others = (self: string) => SALARY_FIELDS.filter((f) => f !== self)

/**
 * Structured salary range: all four fields together or none (send all null to clear). The
 * display text `salary` ("USD 120,000 – 150,000 / year") is generated by the server.
 */
export class JobSalaryFields {
  @ApiPropertyOptional({ example: 120000 })
  @RequiredWith(others("salaryMin"), { message: "Enter the minimum salary" })
  @IfGroupPresent(SALARY_FIELDS)
  @IsInt({ message: "Minimum salary must be a whole number" })
  @Min(0, { message: "Minimum salary can't be negative" })
  @Max(SALARY_MAX_VALUE, { message: "Minimum salary is too large" })
  salaryMin?: number | null

  @ApiPropertyOptional({ example: 150000 })
  @RequiredWith(others("salaryMax"), { message: "Enter the maximum salary" })
  @IfGroupPresent(SALARY_FIELDS)
  @IsInt({ message: "Maximum salary must be a whole number" })
  @Min(0, { message: "Maximum salary can't be negative" })
  @Max(SALARY_MAX_VALUE, { message: "Maximum salary is too large" })
  @IsGreaterOrEqualTo("salaryMin", { message: "Maximum salary must be at least the minimum" })
  salaryMax?: number | null

  @ApiPropertyOptional({ enum: CURRENCIES, example: "USD" })
  @RequiredWith(others("salaryCurrency"), { message: "Choose a currency" })
  @IfGroupPresent(SALARY_FIELDS)
  @IsIn(CURRENCIES as unknown as string[], { message: "Choose a supported currency" })
  salaryCurrency?: string | null

  @ApiPropertyOptional({ enum: SALARY_PERIODS, example: "YEAR" })
  @RequiredWith(others("salaryPeriod"), { message: "Choose per year, month or hour" })
  @IfGroupPresent(SALARY_FIELDS)
  @IsIn(SALARY_PERIODS as unknown as string[], { message: "Choose per year, month or hour" })
  salaryPeriod?: "YEAR" | "MONTH" | "HOUR" | null
}
